"""Self-contained UI; no CDN or build dependencies."""

PAGE = r'''<!doctype html>
<html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>小海 · 记忆工作台</title>
<style>
:root{font:16px/1.6 system-ui,sans-serif;color:#18394a;background:#eef5f7}body{max-width:1100px;margin:auto;padding:28px}h1{margin:0}header{margin-bottom:24px}section{background:white;border:1px solid #dbe7eb;border-radius:16px;padding:22px;margin:18px 0}h2{margin:0 0 12px;font-size:21px}.muted{color:#5b7480}button{cursor:pointer;border:1px solid #b6ced8;border-radius:8px;padding:7px 12px;background:#f7fbfc;color:#17475a;margin:3px}button:hover{background:#e1f0f4}input,textarea{font:inherit;border:1px solid #afc7d1;border-radius:8px;padding:10px;box-sizing:border-box}input[type=text],textarea{width:100%}textarea{min-height:80px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:10px;border-bottom:1px solid #e6eef1;vertical-align:top}pre{white-space:pre-wrap;overflow-wrap:anywhere}#notice{color:#86380c;white-space:pre-wrap}#conversation{max-height:260px;overflow:auto;white-space:pre-wrap}.scroll{overflow:auto}.danger{color:#a12a28}.actions{min-width:230px}small{display:block;color:#5b7480}
</style>
<header><p class="muted">HHU AI AVATAR / 本机工作台</p><h1>小海的记忆与日程</h1><p class="muted">单用户模式 · 各会话共享同一用户的长期记忆</p><div id="state"></div><div id="notice" role="status"></div></header>
<section><h2>对话与召回反馈</h2><div id="conversation" aria-live="polite"></div><form id="chatForm"><label for="chat">和小海说句话</label><textarea id="chat" required placeholder="例如：我叫小林，喜欢游泳。"></textarea><label><input id="useWeb" type="checkbox"> 本轮允许使用网页、天气、资料和提醒工具</label><button>发送</button></form><small id="recalled">这里会显示本轮召回的记忆编号，可在下表标记不相关。</small><div id="webResults" aria-live="polite"></div></section>
<section><h2>长期记忆</h2><label><input id="history" type="checkbox"> 显示历史版本</label><button id="refresh">刷新</button><div class="scroll"><table><thead><tr><th>编号 / 状态</th><th>记忆</th><th>召回状态</th><th>操作</th></tr></thead><tbody id="memories"></tbody></table></div><pre id="detail"></pre></section>
<section><h2>会话摘要与来源</h2><p class="muted">长对话溢出窗口后，保留关键用户原话及消息编号。它是历史讨论线索，不是当前事实；纠错或删除会清空旧摘要。</p><pre id="summary">尚无需要压缩的历史对话。</pre></section>
<section><h2>未来事件</h2><p class="muted">仅明确创建提醒。北京时间；页面打开时每 15 秒检查到期事项。关闭程序期间不会推送，超过一天的旧提醒仅保留在列表中。</p><form id="reminderForm"><label for="reminder">提醒内容</label><input type="text" id="reminder" required placeholder="提醒我明天下午3点答辩"><button>创建提醒</button></form><div class="scroll"><table><thead><tr><th>事项</th><th>北京时间</th><th>状态</th><th>操作</th></tr></thead><tbody id="reminders"></tbody></table></div></section>
<script nonce="__NONCE__">
const token=location.hash.slice(1)||sessionStorage.getItem('avatar-token')||'';if(token)sessionStorage.setItem('avatar-token',token);history.replaceState(null,'',location.pathname);const $=id=>document.getElementById(id);
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'X-Avatar-Token':token,'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.error||'请求失败');return v;}
function notice(error){$('notice').textContent=String(error.message||error)}
function cell(tr,text){const td=document.createElement('td');td.textContent=text;tr.append(td);return td}
function button(td,label,action,danger=false){const b=document.createElement('button');b.textContent=label;if(danger)b.className='danger';b.onclick=async()=>{try{await action();await refresh()}catch(e){notice(e)}};td.append(b)}
function chinaTime(ts){return new Date(ts*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}
async function refresh(){
 const [m,r,s,c]=await Promise.all([api('memories'+($('history').checked?'?history=1':'')),api('reminders'),api('state'),api('summary')]);
 $('summary').replaceChildren();if(!c.summary.items.length)$('summary').textContent='尚无需要压缩的历史对话。';for(const item of c.summary.items){const entry=document.createElement('div');const quote=document.createElement('p');quote.textContent=`消息 #${item.message_id} · ${chinaTime(item.created_at)}\n${item.text}`;entry.append(quote);button(entry,'删除此原话',async()=>{if(confirm('彻底删除这条原话及关联记忆？无法恢复。'))await api('forget-summary-source',{id:item.message_id})},true);$('summary').append(entry)}
 $('state').textContent=`角色活跃度 ${Math.round(s.energy*100)}% · 愉悦度 ${s.valence.toFixed(2)} · 唤醒度 ${s.arousal.toFixed(2)}`;
 $('memories').replaceChildren();for(const row of m.memories){const tr=document.createElement('tr');cell(tr,`${row.id} / ${row.status}`);cell(tr,row.content);cell(tr,`不相关反馈 ${row.bad_hits} 次；时间保留 ${Math.round(row.strength*100)}%`);const actions=cell(tr,'');actions.className='actions';button(actions,'来源',async()=>{$('detail').textContent=JSON.stringify((await api('memory?id='+row.id)).memory,null,2)});button(actions,'纠正',async()=>{const content=prompt('更正内容（会保留历史版本）',row.content);if(content!==null)await api('correct',{id:row.id,content})});if(row.status==='active')button(actions,'召回不相关',()=>api('badhit',{id:row.id}));button(actions,'彻底删除',async()=>{if(confirm('删除此记忆的整个版本链和关联来源？无法恢复。')){await api('forget',{id:row.id});$('detail').textContent=''}},true);$('memories').append(tr)}
 $('reminders').replaceChildren();for(const row of r.reminders){const tr=document.createElement('tr');cell(tr,row.title);cell(tr,chinaTime(row.due_at));cell(tr,row.status+(row.notified_at?' / 已标记到期，显示未确认':''));const actions=cell(tr,'');if(row.status==='active'){button(actions,'完成',()=>api('reminder-status',{id:row.id,status:'completed'}));button(actions,'取消',()=>api('reminder-status',{id:row.id,status:'cancelled'}))}button(actions,'删除',()=>api('delete-reminder',{id:row.id}),true);$('reminders').append(tr)}
}
$('refresh').onclick=()=>refresh().catch(notice);$('history').onchange=$('refresh').onclick;
$('chatForm').onsubmit=async e=>{e.preventDefault();const text=$('chat').value;const b=e.submitter;b.disabled=true;const use_web=$('useWeb').checked;$('webResults').textContent=use_web?'正在连接联网工具，搜索或阅读可能需要一些时间……':'';try{const r=await api('chat',{text,use_web});$('conversation').textContent+=`你：${text}\n小海：${r.reply}\n\n`;$('recalled').textContent='本轮召回编号：'+(r.recalled_ids.join('、')||'无')+'；回应策略：'+r.strategy;$('webResults').replaceChildren();for(const step of r.tool_calls||[]){const p=document.createElement('p');p.textContent=`${step.tool} · ${step.status} · ${step.routing||''}${step.error?'：'+step.error:''}`;$('webResults').append(p)}for(const source of r.sources||[]){try{const url=new URL(source.url);if(!['http:','https:'].includes(url.protocol))continue;const p=document.createElement('p');const a=document.createElement('a');a.href=url.href;a.textContent=(source.kind==='page'?'已读正文：':'搜索结果：')+source.title;a.target='_blank';a.rel='noopener noreferrer';p.append(a);$('webResults').append(p)}catch{}}if(r.web_error)notice('联网服务暂时不可用，请检查可选依赖和网络。');$('chat').value='';await refresh()}catch(err){notice(err)}finally{b.disabled=false}};
$('reminderForm').onsubmit=async e=>{e.preventDefault();try{await api('reminders',{text:$('reminder').value});$('reminder').value='';await refresh()}catch(err){notice(err)}};
async function poll(){try{const r=await api('due',{});if(r.reminders.length){notice('到期提醒：'+r.reminders.map(x=>x.title).join('；'));await refresh()}}catch(e){notice(e)}}
refresh().then(poll).catch(notice);setInterval(poll,15000);
</script></html>'''
